const NONE = -1;

/**
 * Fixed-capacity LRU cache: a hash index over an intrusive doubly linked
 * recency list. Every operation runs in O(1) expected time.
 *
 * List nodes live in parallel arrays addressed by slot number. Since the cache
 * never holds more than `capacity` entries, at most `capacity + 1` slots are
 * ever needed, and freed slots are recycled through a free list.
 */
export class LruCache<K, V> {
  readonly #capacity: number;
  readonly #index = new Map<K, number>();
  readonly #keys: K[] = [];
  readonly #values: V[] = [];
  #prev: Int32Array;
  #next: Int32Array;
  #head = NONE; // most recently used
  #tail = NONE; // least recently used
  #freeSlots: number[] = [];

  constructor(capacity: number) {
    this.#capacity = capacity;
    const initial = Math.min(capacity + 1, 1024);
    this.#prev = new Int32Array(initial);
    this.#next = new Int32Array(initial);
  }

  get size(): number {
    return this.#index.size;
  }

  /** Inserts or overwrites `key`, making it the most recently used. */
  set(key: K, value: V): void {
    const existing = this.#index.get(key);
    if (existing !== undefined) {
      this.#values[existing] = value;
      this.#touch(existing);
      return;
    }

    const slot = this.#allocate();
    this.#keys[slot] = key;
    this.#values[slot] = value;
    this.#pushFront(slot);
    this.#index.set(key, slot);

    if (this.#index.size > this.#capacity) this.#remove(this.#tail);
  }

  /** Returns the value for `key` (marking it most recently used), or `undefined` on a miss. */
  get(key: K): V | undefined {
    const slot = this.#index.get(key);
    if (slot === undefined) return undefined;
    this.#touch(slot);
    return this.#values[slot];
  }

  /** Removes `key`; returns whether it was present. */
  delete(key: K): boolean {
    const slot = this.#index.get(key);
    if (slot === undefined) return false;
    this.#remove(slot);
    return true;
  }

  #allocate(): number {
    const recycled = this.#freeSlots.pop();
    if (recycled !== undefined) return recycled;
    const slot = this.#keys.length;
    if (slot === this.#prev.length) this.#grow();
    return slot;
  }

  #grow(): void {
    const length = Math.min(this.#prev.length * 2, this.#capacity + 1);
    const prev = new Int32Array(length);
    const next = new Int32Array(length);
    prev.set(this.#prev);
    next.set(this.#next);
    this.#prev = prev;
    this.#next = next;
  }

  #remove(slot: number): void {
    this.#index.delete(this.#keys[slot]);
    this.#unlink(slot);
    // Drop references so evicted entries can be garbage-collected.
    this.#keys[slot] = undefined as K;
    this.#values[slot] = undefined as V;
    this.#freeSlots.push(slot);
  }

  #touch(slot: number): void {
    if (slot === this.#head) return;
    this.#unlink(slot);
    this.#pushFront(slot);
  }

  #pushFront(slot: number): void {
    this.#prev[slot] = NONE;
    this.#next[slot] = this.#head;
    if (this.#head === NONE) this.#tail = slot;
    else this.#prev[this.#head] = slot;
    this.#head = slot;
  }

  #unlink(slot: number): void {
    const prev = this.#prev[slot];
    const next = this.#next[slot];
    if (prev === NONE) this.#head = next;
    else this.#next[prev] = next;
    if (next === NONE) this.#tail = prev;
    else this.#prev[next] = prev;
  }
}

// LRU cache simulator: reads a capacity and a stream of commands from stdin.
import { LruCache } from './lru-cache.ts';

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
  // Keys and values are printable ASCII; latin1 maps bytes 1:1 and round-trips any input.
  return Buffer.concat(chunks).toString('latin1');
}

/** Parses the leading decimal digits of `s`; anything after them is ignored. */
function parseCapacity(s: string): number {
  let value = 0;
  for (let i = 0; i < s.length; i++) {
    const digit = s.charCodeAt(i) - 48;
    if (digit < 0 || digit > 9) break;
    value = value * 10 + digit;
  }
  return value;
}

/** Yields each `\n`-terminated line (the last may be unterminated), stripping a trailing `\r`. */
function* lines(data: string): Generator<string> {
  let start = 0;
  while (start < data.length) {
    let end = data.indexOf('\n', start);
    if (end === -1) end = data.length;
    const lineEnd = end > start && data.charCodeAt(end - 1) === 13 ? end - 1 : end;
    yield data.slice(start, lineEnd);
    start = end + 1;
  }
}

/** Returns the `index`-th single-space-delimited token of `line`, or `''` if absent. */
function token(line: string, index: number): string {
  let start = 0;
  for (let i = 0; i < index; i++) {
    const space = line.indexOf(' ', start);
    if (space === -1) return '';
    start = space + 1;
  }
  const end = line.indexOf(' ', start);
  return end === -1 ? line.slice(start) : line.slice(start, end);
}

function run(input: string): string {
  const it = lines(input);
  const first = it.next();
  if (first.done) return '';

  const cache = new LruCache<string, string>(parseCapacity(first.value));
  const out: string[] = [];

  for (const line of it) {
    switch (token(line, 0)) {
      case 'SET':
        cache.set(token(line, 1), token(line, 2));
        break;
      case 'GET':
        out.push(cache.get(token(line, 1)) ?? 'NULL');
        break;
      case 'DEL':
        out.push(cache.delete(token(line, 1)) ? '1' : '0');
        break;
      case 'SIZE':
        out.push(String(cache.size));
        break;
    }
  }

  return out.length === 0 ? '' : out.join('\n') + '\n';
}

const output = run(await readStdin());
if (output.length > 0) process.stdout.write(Buffer.from(output, 'latin1'));
